name: Resolve agent key from PR labels
        id: agent
        if: steps.context.outputs.should_run == 'true'
        uses: actions/github-script@v9
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            // # best-effort: this ancillary API failure is logged; reconciliation or the primary workflow result remains authoritative.
            const fs = require('fs');
            const retryHelperPath = './.workflows-lib/.github/scripts/github-api-with-retry.js';
            const retryHelpers = fs.existsSync(retryHelperPath)
              ? require(retryHelperPath)
              : { withRetry: (fn) => fn() };
            const { withRetry } = retryHelpers;

            const registryPath = './.workflows-lib/.github/agents/registry.yml';
            const resolverPath = './.workflows-lib/.github/scripts/agent_registry.js';

            // Resolve agent from PR labels; fall back to registry default
            let _defaultAgent = 'codex';
            try {
              const { loadAgentRegistry } = require(resolverPath);
              _defaultAgent = loadAgentRegistry({ registryPath }).default_agent || 'codex';
            } catch (_) {}
            let agentKey = _defaultAgent;
            try {
              const { resolveAgentFromLabels } = require(resolverPath);
              const rawPrNumber = Number('${{ steps.context.outputs.pr_number }}');
              const prNumber = !Number.isNaN(rawPrNumber) && rawPrNumber > 0 ? rawPrNumber : null;

              let labels = [];
              if (prNumber) {
                const { data: pr } = await withRetry(() => github.rest.pulls.get({
                  ...context.repo,
                  pull_number: prNumber,
                }));
                labels = Array.isArray(pr.labels) ? pr.labels : [];
              }

              agentKey = resolveAgentFromLabels(labels, { registryPath });
            } catch (err) {
                core.warning(
                  [
                    `Failed to resolve agent from PR labels; defaulting to ${_defaultAgent}:`,
                    err.message,
                  ].join(' '),
                );
              agentKey = _defaultAgent;
            }

            const normalized =
              String(agentKey || _defaultAgent).trim().toLowerCase() ||
              _defaultAgent;
            core.setOutput('agent_key', normalized);
            core.setOutput('agent_label', `agent:${normalized}`);
            core.setOutput('from_label', `from:${normalized}`);

