            const retryHelpers = fs.existsSync(retryHelperPath)
              ? require(retryHelperPath)
              : {
                  withRetry: (fn) => fn(),
                  paginateWithRetry: (githubInstance, method, params) =>
                    githubInstance.paginate(method, params),
                };
            const { withRetry } = retryHelpers;
            const {
              formatFollowUpIssue,
              formatSimpleFollowUpIssue,
            } = require('./.workflows-lib/.github/scripts/verifier_issue_formatter.js');

            const rawPrNumber = Number('${{ steps.context.outputs.pr_number }}');
            const prNumber = !Number.isNaN(rawPrNumber) && rawPrNumber > 0 ? rawPrNumber : null;
            const issueNumbers = JSON.parse(process.env.ISSUE_NUMBERS_JSON || '[]');
            const verdict = '${{ steps.verdict.outputs.verdict }}';
            const prUrl = process.env.PR_URL || '';
            const runUrl = process.env.RUN_URL || '';

            // Agent labels resolved in the 'agent' step; derive from agent_key
            // when the label output is missing.
            const agentKey = '${{ steps.agent.outputs.agent_key }}' || 'codex';
            const agentLabel = '${{ steps.agent.outputs.agent_label }}' || `agent:${agentKey}`;
            const fromLabel = '${{ steps.agent.outputs.from_label }}' || `from:${agentKey}`;

            // Handle agent crash/error case
            if (verdict === 'error') {
              const title = prNumber
                ? `[Verifier Error] PR #${prNumber} verification failed`
                : '[Verifier Error] Verification failed';
              const body = [
                '## Verifier Error',
                '',
                'The verifier encountered an error while checking acceptance criteria.',
                '',
                `**PR:** ${prUrl || `#${prNumber}` || 'unknown'}`,
                `**Run:** ${runUrl}`,
                '',
                'Please review the workflow run logs for details.',
              ].join('\n');
              const { data: issue } = await withRetry(() => github.rest.issues.create({
                ...context.repo,
                title,
                body,
                labels: [agentLabel, fromLabel, 'bug'],
              }));
              core.setOutput('issue_number', issue?.number ? String(issue.number) : '');
              core.info(`Created error follow-up issue #${issue.number}: ${title}`);
              return;
            }

            // Normal failure case - verifier ran but criteria weren't met
            let verifierOutput = '';
            try {
              verifierOutput = fs.readFileSync('codex-output.md', 'utf8');
            } catch (err) {
              core.warning(`Could not read codex-output.md: ${err.message}`);
              verifierOutput = '_Verifier output not available_';
            }

            let prBody = '';
            if (prNumber) {
              try {
                const { data: pr } = await withRetry(() => github.rest.pulls.get({
                  ...context.repo,
                  pull_number: prNumber,
                }));
                prBody = pr.body || '';
              } catch (err) {
                core.warning(`Failed to fetch PR body: ${err.message}`);
              }
            }

            const issues = [];
            for (const issueNum of issueNumbers) {
              try {
                const { data: issue } = await withRetry(() => github.rest.issues.get({
                  ...context.repo,
                  issue_number: issueNum,
                }));
                issues.push({
                  number: issue.number,
                  title: issue.title || '',
                  body: issue.body || '',
                });
              } catch (err) {
                core.warning(`Failed to fetch issue #${issueNum}: ${err.message}`);
              }
            }

            let result;
            if (prBody || issues.length > 0) {
              result = formatFollowUpIssue({
                verifierOutput,
                prBody,
                issues,
                prNumber,
                prUrl,
                runUrl,
              });
            } else {
              result = formatSimpleFollowUpIssue({
                verifierOutput,
                prNumber,
                prUrl,
                issueNumbers,
                runUrl,
              });
            }

            // Skip issue creation if there's no substantive content
            // (e.g., all sections are placeholder text or empty)
            if (!result.hasSubstantiveContent) {
              core.info(
                [
                  "Skipping issue creation: no substantive content to act on",
                  "(all placeholder sections).",
                ].join(' '),
              );
              core.setOutput('issue_number', '');
              core.setOutput('skipped', 'true');
              return;
            }

            const { data: issue } = await withRetry(() => github.rest.issues.create({
              ...context.repo,
              title: result.title,
              body: result.body,
              labels: [agentLabel, fromLabel],
            }));
            core.setOutput('issue_number', issue?.number ? String(issue.number) : '');
            core.setOutput('skipped', 'false');
            core.info(`Created follow-up issue #${issue.number}: ${result.title}`);

